<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Penerimaan', href: '/owner/payments' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';
    type Payment = { id: number; amount_rupiah: number; occurred_on: string; method: string; category: string; description: string | null; external_reference: string | null; allocations: { target: string; amount_rupiah: number; resident: string | null }[] };
    type Page<T> = { data: T[]; links: { url: string | null; label: string; active: boolean }[]; from: number | null; to: number | null; total: number };
    let { payments, filters }: { payments: Page<Payment>; filters: { from: string; to: string; method: string } } = $props();
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
    const categoryLabel: Record<string, string> = { rent_receipt: 'Penerimaan sewa', mixed_receipt: 'Penerimaan sewa + deposit', deposit_receipt: 'Penerimaan deposit' };
</script>

<AppHead title="Penerimaan" />
<main class="space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-end justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Keuangan</p><h1 class="text-3xl font-semibold tracking-tight">Penerimaan</h1><p class="text-sm text-muted-foreground">Setiap transfer tercatat sekali, dengan alokasi sewa dan deposit yang terpisah.</p></div><Link href="/owner/payments/create" class="inline-flex rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Catat transfer</Link></header>
    <Form action="/owner/payments" method="get" class="grid gap-3 rounded-xl border bg-card p-4 sm:grid-cols-4 sm:items-end">{#snippet children({ processing })}<div class="space-y-1"><label for="from" class="text-sm font-medium">Dari tanggal</label><Input id="from" name="from" type="date" value={filters.from} /></div><div class="space-y-1"><label for="to" class="text-sm font-medium">Sampai tanggal</label><Input id="to" name="to" type="date" value={filters.to} /></div><div class="space-y-1"><label for="method" class="text-sm font-medium">Metode</label><select id="method" name="method" value={filters.method} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Semua metode</option><option value="bank_transfer">Transfer bank</option><option value="cash">Tunai</option><option value="e_wallet">Dompet digital</option><option value="other">Lainnya</option></select></div><Button type="submit" disabled={processing}>Terapkan</Button>{/snippet}</Form>
    <section class="overflow-hidden rounded-xl border bg-card shadow-sm" aria-label="Riwayat penerimaan">{#if payments.data.length === 0}<div class="p-10 text-center"><h2 class="font-medium">Belum ada penerimaan</h2><p class="mt-1 text-sm text-muted-foreground">Catat transfer yang benar-benar sudah diterima.</p></div>{:else}<div class="overflow-x-auto"><table class="w-full min-w-[52rem] text-left text-sm"><thead class="border-b bg-muted/40 text-muted-foreground"><tr><th class="px-5 py-3 font-medium">Tanggal / referensi</th><th class="px-5 py-3 font-medium">Kategori</th><th class="px-5 py-3 font-medium">Alokasi</th><th class="px-5 py-3 text-right font-medium">Transfer aktual</th><th class="px-5 py-3 text-right font-medium">Aksi</th></tr></thead><tbody class="divide-y">{#each payments.data as payment (payment.id)}<tr><td class="px-5 py-4"><p class="font-medium">{payment.occurred_on}</p><p class="text-xs text-muted-foreground">{payment.external_reference ?? payment.method}</p></td><td class="px-5 py-4">{categoryLabel[payment.category] ?? payment.category}</td><td class="px-5 py-4">{#each payment.allocations as allocation, index (index)}<p>{allocation.target}{allocation.resident ? ` · ${allocation.resident}` : ''}: {money(allocation.amount_rupiah)}</p>{/each}</td><td class="px-5 py-4 text-right font-medium">{money(payment.amount_rupiah)}</td><td class="px-5 py-4 text-right"><Link href={`/owner/payments/${payment.id}`} class="text-primary underline-offset-4 hover:underline">Detail</Link></td></tr>{/each}</tbody></table></div><footer class="flex flex-wrap items-center justify-between gap-4 border-t px-5 py-4 text-sm"><p class="text-muted-foreground">Menampilkan {payments.from ?? 0}–{payments.to ?? 0} dari {payments.total} penerimaan</p><nav aria-label="Navigasi halaman" class="flex flex-wrap gap-1">{#each payments.links as link, index (index)}{#if link.url}<Link href={link.url} class={`rounded border px-3 py-1.5 ${link.active ? 'bg-primary text-primary-foreground' : 'hover:bg-muted'}`}>{link.label}</Link>{:else}<span class="rounded border px-3 py-1.5 text-muted-foreground">{link.label}</span>{/if}{/each}</nav></footer>{/if}</section>
</main>
